#!/usr/bin/env node
// Nordle validator: JSON Schema plus the cross-reference checks a schema cannot express
// (brand tokens resolve, sizes exist, layer ids are unique, clips fit their sources, paths stay inside the project).
//
//   node tools/validate.mjs [--assets] [--media] [--json] [paths...]
//
// --assets  also require images, logos and fonts to exist on disk
// --media   also require files under sources/ (generated by tools/make-sample-media.mjs)
// With no paths it checks data/, samples/ and examples/.

import { readFileSync, readdirSync, existsSync, statSync } from 'node:fs';
import { dirname, join, resolve, relative, sep, basename } from 'node:path';
import { fileURLToPath } from 'node:url';
import Ajv2020 from 'ajv/dist/2020.js';
import addFormats from 'ajv-formats';
import { resolveToken } from '../src/shared/tokens.mjs';
import { mountRefProblem, resolveMediaPath } from '../src/video/mounts.mjs';
import { loadWordsFile } from '../src/video/words.mjs';

export const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const EPS = 1e-6;
const SKIP_DIRS = new Set(['node_modules', '.git', 'out', 'sources', 'assets', 'cache', 'history']);
const TEXT_KEYS = new Set(['text', 'caption', 'cta', 'notes', 'note', 'alt', 'title', 'name', 'message', 'description']);

export const readJson = (p) => JSON.parse(readFileSync(p, 'utf8'));
const relRoot = (p) => relative(ROOT, p).split(sep).join('/');

let compiled;
export function validators() {
  if (compiled) return compiled;
  const ajv = new Ajv2020({ allErrors: true, strict: true, strictTypes: false, strictRequired: false });
  addFormats(ajv);
  compiled = {};
  for (const name of ['doc', 'brand', 'platforms', 'pack', 'review', 'facts', 'catalog', 'checks', 'calendar']) {
    compiled[name] = ajv.compile(readJson(join(ROOT, 'schemas', `${name}.schema.json`)));
  }
  return compiled;
}

function schemaIssues(validate, data) {
  if (validate(data)) return [];
  return validate.errors
    .filter((e) => e.keyword !== 'if')
    .map((e) => {
      const extra = e.params?.additionalProperty ?? e.params?.missingProperty;
      return { level: 'error', path: e.instancePath || '/', message: extra ? `${e.message}: ${extra}` : e.message };
    });
}

function* walk(node, path = '') {
  if (typeof node === 'string') yield [path, node];
  else if (Array.isArray(node)) for (let i = 0; i < node.length; i++) yield* walk(node[i], `${path}/${i}`);
  else if (node && typeof node === 'object') for (const [k, v] of Object.entries(node)) yield* walk(v, `${path}/${k}`);
}

export { resolveToken };

function makePathChecker(ctx, issues) {
  return (path, rel) => {
    if (rel.startsWith('mount:')) {
      // footage and music that stay where they are: "mount:<name>/<path>", set up per machine in nordle.local.json
      const problem = mountRefProblem(rel);
      if (problem) return issues.push({ level: 'error', path, message: problem });
      if (ctx.media) {
        try {
          if (!existsSync(resolveMediaPath(ctx.projectDir, rel))) issues.push({ level: 'error', path, message: `file not found: ${rel}` });
        } catch (e) { issues.push({ level: 'error', path, message: e.message }); }
      }
      return;
    }
    const abs = resolve(ctx.projectDir, rel);
    const inside = abs === ctx.projectDir || abs.startsWith(ctx.projectDir + sep);
    if (!inside) return issues.push({ level: 'error', path, message: `path "${rel}" leaves the project folder` });
    const isMedia = rel.split('/')[0] === 'sources';
    if ((ctx.assets && !isMedia) || (ctx.media && isMedia)) {
      if (!existsSync(abs)) {
        const hint = isMedia ? ' (run: node tools/make-sample-media.mjs)' : '';
        issues.push({ level: 'error', path, message: `file not found: ${rel}${hint}` });
      }
    }
  };
}

export function checkBrand(brand, ctx = {}) {
  const issues = [];
  const err = (path, message) => issues.push({ level: 'error', path, message });
  for (const [path, value] of walk(brand)) {
    if (!value.startsWith('$brand.')) continue;
    if (resolveToken(value, brand) === undefined) err(path, `brand token ${value} does not resolve`);
  }
  for (const [name, way] of Object.entries(brand.colourways ?? {})) {
    for (const key of Object.keys(way.colors)) {
      if (!Object.hasOwn(brand.colors, key)) err(`/colourways/${name}/colors/${key}`, `colourway changes "${key}" which the brand does not define`);
    }
  }
  if (ctx.projectDir) {
    const checkPath = makePathChecker(ctx, issues);
    for (const [name, p] of Object.entries(brand.logos ?? {})) checkPath(`/logos/${name}`, p);
    for (const [name, font] of Object.entries(brand.fonts ?? {})) {
      for (const [w, p] of Object.entries(font.files ?? {})) checkPath(`/fonts/${name}/files/${w}`, p);
    }
  }
  return issues;
}

export function checkDoc(doc, ctx) {
  const issues = [];
  const err = (path, message) => issues.push({ level: 'error', path, message });
  const warn = (path, message) => issues.push({ level: 'warn', path, message });
  const checkPath = makePathChecker(ctx, issues);

  // sizes
  const presets = new Map((ctx.platforms?.presets ?? []).map((p) => [p.id, p]));
  const sizeIds = [];
  (doc.sizes ?? []).forEach((s, i) => {
    const id = typeof s === 'string' ? s : s.id;
    if (sizeIds.includes(id)) err(`/sizes/${i}`, `duplicate size "${id}"`);
    sizeIds.push(id);
    if (typeof s !== 'string') return;
    const preset = presets.get(s);
    if (!preset) return err(`/sizes/${i}`, `unknown size "${s}" (not in data/platforms.json)`);
    if (!preset.kinds.includes(doc.kind)) warn(`/sizes/${i}`, `"${s}" is not meant for ${doc.kind} posts`);
    if (doc.timeline && preset.maxDuration && doc.timeline.duration > preset.maxDuration) {
      warn(`/sizes/${i}`, `video is ${doc.timeline.duration}s but "${s}" allows ${preset.maxDuration}s (unverified limit)`);
    }
  });

  // brand
  const brand = ctx.brand;
  if (!brand) {
    err('/brand', `brand "${doc.brand}" not found: put a brand.json in the project root`);
  } else {
    if (brand.id !== doc.brand) err('/brand', `document uses brand "${doc.brand}" but the project's brand.json is "${brand.id}"`);
    if (doc.colourway && !brand.colourways?.[doc.colourway]) err('/colourway', `brand has no colourway "${doc.colourway}"`);
    for (const [path, value] of walk(doc)) {
      const key = path.split('/').pop();
      if (!value.startsWith('$brand.') || TEXT_KEYS.has(key)) continue;
      const resolved = resolveToken(value, brand, doc.colourway);
      if (resolved === undefined) err(path, `brand token ${value} does not resolve`);
      else if (key === 'font' ? typeof resolved !== 'object' || !resolved.family : typeof resolved === 'object') {
        err(path, `brand token ${value} is the wrong kind of value here`);
      }
    }
  }

  // sources
  const sourcesById = new Map();
  (doc.sources ?? []).forEach((s, i) => {
    if (sourcesById.has(s.id)) err(`/sources/${i}/id`, `duplicate source id "${s.id}"`);
    sourcesById.set(s.id, s);
    checkPath(`/sources/${i}/path`, s.path);
    if (s.transcript) {
      checkPath(`/sources/${i}/transcript`, s.transcript);
      // a transcript that exists must be readable word timings (a missing one is only an error with --media)
      try {
        const file = resolveMediaPath(ctx.projectDir, s.transcript);
        if (existsSync(file)) {
          const { words } = loadWordsFile(file);
          if (!words.length) warn(`/sources/${i}/transcript`, 'the transcript has no words');
          else if (s.duration && words.at(-1).end > s.duration + 2) warn(`/sources/${i}/transcript`, `the transcript runs to ${words.at(-1).end.toFixed(1)}s but the source is ${s.duration}s long: is it the right file?`);
        }
      } catch (e) {
        if (e?.name === 'WordsError') err(`/sources/${i}/transcript`, `transcript ${s.transcript} is not usable: ${e.message}`);
      }
    }
    if (s.proxy) checkPath(`/sources/${i}/proxy`, s.proxy);
  });

  // layers
  const checkLayers = (layers, base, seen, topLevelOverlay) => {
    layers.forEach((l, i) => {
      const p = `${base}/${i}`;
      if (seen.has(l.id)) err(`${p}/id`, `duplicate layer id "${l.id}"`);
      seen.add(l.id);
      for (const k of Object.keys(l.overrides ?? {})) {
        if (!sizeIds.includes(k)) err(`${p}/overrides/${k}`, `override for size "${k}", which is not in this document's sizes`);
      }
      if (l.stack && l.type !== 'group') err(`${p}/stack`, 'only a group can be a stack');
      if (l.src) checkPath(`${p}/src`, l.src);
      if (l.type === 'video') {
        const s = sourcesById.get(l.source);
        if (!s) err(`${p}/source`, `unknown source "${l.source}"`);
        else if (s.type !== 'video') err(`${p}/source`, `source "${l.source}" is ${s.type}, not video`);
      }
      if (l.time) {
        if (doc.kind !== 'video') err(`${p}/time`, 'time ranges are only for video overlays');
        else {
          if (l.time.end <= l.time.start) err(`${p}/time`, 'end must be after start');
          if (l.time.end > doc.timeline.duration + EPS) err(`${p}/time/end`, `ends at ${l.time.end}s, after the timeline (${doc.timeline.duration}s)`);
        }
      } else if (topLevelOverlay) {
        err(p, `overlay layer "${l.id}" needs a time range`);
      }
      if (l.type === 'group') checkLayers(l.children, `${p}/children`, seen, false);
    });
  };

  const pageIds = new Set();
  (doc.pages ?? []).forEach((page, i) => {
    if (pageIds.has(page.id)) err(`/pages/${i}/id`, `duplicate page id "${page.id}"`);
    pageIds.add(page.id);
    checkLayers(page.layers, `/pages/${i}/layers`, new Set(), false);
  });
  if (doc.layers) checkLayers(doc.layers, '/layers', new Set(), true);

  // alt text keys
  const altTargets = doc.kind === 'video' ? new Set(['video']) : pageIds;
  for (const key of Object.keys(doc.copy?.alt ?? {})) {
    if (!altTargets.has(key)) err(`/copy/alt/${key}`, `alt text for "${key}", which is not a ${doc.kind === 'video' ? 'video' : 'page id'} in this document`);
  }

  // timeline
  const t = doc.timeline;
  if (t) {
    const trackIds = new Set();
    t.tracks.forEach((tr, ti) => {
      if (trackIds.has(tr.id)) err(`/timeline/tracks/${ti}/id`, `duplicate track id "${tr.id}"`);
      trackIds.add(tr.id);
    });
    const clipIds = new Set();
    t.tracks.forEach((tr, ti) => {
      const spans = [];
      tr.clips.forEach((c, ci) => {
        const p = `/timeline/tracks/${ti}/clips/${ci}`;
        if (clipIds.has(c.id)) err(`${p}/id`, `duplicate clip id "${c.id}"`);
        clipIds.add(c.id);
        const src = sourcesById.get(c.source);
        if (!src) err(`${p}/source`, `unknown source "${c.source}"`);
        else {
          const fits = tr.type === 'audio' ? src.type === 'audio' : src.type !== 'audio';
          if (!fits) err(`${p}/source`, `a ${tr.type} track cannot use the ${src.type} source "${c.source}"`);
          if (src.duration && c.out > src.duration + EPS) err(`${p}/out`, `out (${c.out}s) is past the end of source "${src.id}" (${src.duration}s)`);
        }
        if (c.out <= c.in) err(`${p}/out`, 'out must be after in');
        const end = c.at + (c.out - c.in) / (c.speed ?? 1);
        if (end > t.duration + EPS) err(p, `clip ends at ${end.toFixed(2)}s, after the timeline (${t.duration}s)`);
        if (c.duck) {
          if (!trackIds.has(c.duck.under)) err(`${p}/duck/under`, `unknown track "${c.duck.under}"`);
          else if (c.duck.under === tr.id) err(`${p}/duck/under`, 'a clip cannot duck under its own track');
        }
        // picture fields only mean something on a video track
        if (tr.type === 'audio') {
          for (const k of ['zoom', 'pan', 'grade', 'denoise', 'transition', 'focal', 'fit']) if (c[k] !== undefined) warn(`${p}/${k}`, `"${k}" has no effect on an audio track`);
        } else {
          if (src?.type === 'image' && c.speed !== undefined && c.speed !== 1) warn(`${p}/speed`, 'speed has no effect on a photo');
          if (c.transition && c.transition.type !== 'cut' && ci === 0 && !tr.clips.some((o) => o !== c && o.at < c.at)) warn(`${p}/transition`, 'there is no clip before this one, so the transition does nothing');
        }
        spans.push({ id: c.id, start: c.at, end });
      });
      spans.sort((a, b) => a.start - b.start);
      for (let i = 1; i < spans.length; i++) {
        if (spans[i].start < spans[i - 1].end - EPS) {
          err(`/timeline/tracks/${ti}`, `clips "${spans[i - 1].id}" and "${spans[i].id}" overlap on track "${tr.id}"`);
        }
      }
    });
    const sceneIds = new Set();
    (t.scenes ?? []).forEach((s, i) => {
      const p = `/timeline/scenes/${i}`;
      if (sceneIds.has(s.id)) err(`${p}/id`, `duplicate scene id "${s.id}"`);
      sceneIds.add(s.id);
      if (s.end <= s.start) err(p, 'scene end must be after start');
      if (s.end > t.duration + EPS) err(`${p}/end`, `scene ends at ${s.end}s, after the timeline (${t.duration}s)`);
    });
    if (t.captions) {
      const src = sourcesById.get(t.captions.source);
      if (!src) err('/timeline/captions/source', `unknown source "${t.captions.source}"`);
      else if (!src.transcript) warn('/timeline/captions/source', `source "${src.id}" has no transcript, so there are no words to caption`);
    }
  }
  return issues;
}

export function checkPack(pack) {
  const issues = [];
  const ids = new Set();
  (pack.rules ?? []).forEach((r, i) => {
    const p = `/rules/${i}`;
    if (ids.has(r.id)) issues.push({ level: 'error', path: `${p}/id`, message: `duplicate rule id "${r.id}"` });
    ids.add(r.id);
    if (r.type === 'regex') {
      try { new RegExp(r.pattern, r.flags ?? ''); } catch (e) {
        issues.push({ level: 'error', path: `${p}/pattern`, message: `invalid regular expression: ${e.message}` });
      }
    }
  });
  if (pack.runsCode) issues.push({ level: 'warn', path: '/runsCode', message: 'this pack declares that it runs code: users must approve it before use' });
  return issues;
}

export function checkPlatforms(data) {
  const issues = [];
  const ids = new Set();
  data.presets.forEach((p, i) => {
    if (ids.has(p.id)) issues.push({ level: 'error', path: `/presets/${i}/id`, message: `duplicate preset id "${p.id}"` });
    ids.add(p.id);
  });
  const unverified = data.presets.filter((p) => !p.verified).length;
  if (unverified) issues.push({ level: 'warn', path: '/presets', message: `${unverified} of ${data.presets.length} presets are not verified against platform guidance yet` });
  return issues;
}

/** A calendar: unique item ids, real dates, and (inside a project) built items must point at a document that exists. */
function checkCalendar(cal, dir) {
  const issues = [];
  const seen = new Set();
  const isProject = existsSync(join(dir, 'brand.json'));
  (cal.items ?? []).forEach((it, i) => {
    if (seen.has(it.id)) issues.push({ level: 'error', path: `/items/${i}/id`, message: `duplicate item id "${it.id}"` });
    seen.add(it.id);
    const [y, m, d] = it.date.split('-').map(Number);
    if (d > new Date(Date.UTC(y, m, 0)).getUTCDate()) issues.push({ level: 'error', path: `/items/${i}/date`, message: `"${it.date}" is not a real date` });
    if (it.doc && isProject && !existsSync(join(dir, 'docs', `${it.doc}.json`))) issues.push({ level: 'error', path: `/items/${i}/doc`, message: `item "${it.id}" points at document "${it.doc}", which does not exist in docs/` });
    if (['built', 'signed-off', 'posted', 'changes'].includes(it.status) && !it.doc && !it.external) issues.push({ level: 'warn', path: `/items/${i}`, message: `item "${it.id}" is ${it.status} but has no document` });
  });
  return issues;
}

function kindOf(data) {
  const s = data?.schema;
  if (typeof s !== 'string' || !s.startsWith('nordle.')) return null;
  const m = /^nordle\.(doc|brand|platforms|pack|review|facts|catalog|checks|calendar)\/0\.1$/.exec(s);
  return m ? m[1] : 'unsupported';
}

function findProject(startDir) {
  let dir = startDir;
  for (let i = 0; i < 5; i++) {
    const candidate = join(dir, 'brand.json');
    if (existsSync(candidate)) return { dir, brandFile: candidate };
    const up = dirname(dir);
    if (up === dir) break;
    dir = up;
  }
  return null;
}

const brandCache = new Map();
export function projectFor(file) {
  const found = findProject(dirname(file));
  if (!found) return { projectDir: dirname(dirname(file)), brand: null };
  if (!brandCache.has(found.brandFile)) {
    try { brandCache.set(found.brandFile, readJson(found.brandFile)); } catch { brandCache.set(found.brandFile, null); }
  }
  return { projectDir: found.dir, brand: brandCache.get(found.brandFile) };
}

/** Validate a document that is held in memory (used by the editor before it saves an edit). */
export function validateDocData(doc, { brand, projectDir, platforms, assets = true }) {
  const issues = schemaIssues(validators().doc, doc);
  if (issues.length) return issues;
  return checkDoc(doc, { brand, platforms, projectDir, assets, media: false });
}

/** Validate a review file held in memory. */
export function validateReviewData(review) {
  return schemaIssues(validators().review, review);
}

export function validateFile(file, opts = {}) {
  let data;
  try { data = readJson(file); } catch (e) { return { file, kind: null, issues: [{ level: 'error', path: '/', message: `not valid JSON: ${e.message}` }] }; }
  const kind = kindOf(data);
  if (kind === null) return { file, kind: null, issues: [], skipped: true };
  if (kind === 'unsupported') return { file, kind, issues: [{ level: 'error', path: '/schema', message: `unsupported schema "${data.schema}"` }] };
  const v = validators();
  const issues = schemaIssues(v[kind], data);
  if (issues.length) return { file, kind, issues };   // do not cross-check a document that is not even the right shape
  if (kind === 'doc') {
    const { projectDir, brand } = projectFor(file);
    issues.push(...checkDoc(data, { brand, platforms: opts.platforms ?? readJson(join(ROOT, 'data', 'platforms.json')), projectDir, assets: opts.assets, media: opts.media }));
  } else if (kind === 'brand') {
    issues.push(...checkBrand(data, { projectDir: dirname(file), assets: opts.assets, media: opts.media }));
  } else if (kind === 'pack') {
    issues.push(...checkPack(data));
  } else if (kind === 'platforms') {
    issues.push(...checkPlatforms(data));
  } else if (kind === 'calendar') {
    issues.push(...checkCalendar(data, dirname(file)));
  }
  return { file, kind, issues };
}

function collect(target, out = []) {
  const st = statSync(target);
  if (st.isFile()) { out.push(target); return out; }
  for (const name of readdirSync(target)) {
    if (SKIP_DIRS.has(name)) continue;
    const p = join(target, name);
    const s = statSync(p);
    if (s.isDirectory()) collect(p, out);
    else if (name.endsWith('.json') && name !== 'package.json' && name !== 'package-lock.json') out.push(p);
  }
  return out;
}

export function validateAll(targets, opts = {}) {
  const files = targets.flatMap((t) => collect(resolve(t)));
  return files.map((f) => validateFile(f, opts)).filter((r) => !r.skipped);
}

function main() {
  const args = process.argv.slice(2);
  const flags = new Set(args.filter((a) => a.startsWith('--')));
  const targets = args.filter((a) => !a.startsWith('--'));
  const opts = { assets: flags.has('--assets'), media: flags.has('--media') };
  const results = validateAll(targets.length ? targets : [join(ROOT, 'data'), join(ROOT, 'samples'), join(ROOT, 'examples')], opts);

  if (flags.has('--json')) {
    console.log(JSON.stringify(results.map((r) => ({ ...r, file: relRoot(r.file) })), null, 2));
  } else {
    let errors = 0, warnings = 0;
    for (const r of results) {
      const e = r.issues.filter((i) => i.level === 'error').length;
      const w = r.issues.length - e;
      errors += e; warnings += w;
      console.log(`${e ? 'FAIL' : 'OK  '} ${relRoot(r.file)}  (${r.kind}${w ? `, ${w} warning${w > 1 ? 's' : ''}` : ''})`);
      for (const i of r.issues) console.log(`     ${i.level === 'error' ? 'error' : 'warn '} ${i.path}: ${i.message}`);
    }
    console.log(`\n${results.length} files checked, ${errors} error${errors === 1 ? '' : 's'}, ${warnings} warning${warnings === 1 ? '' : 's'}.`);
  }
  process.exitCode = results.some((r) => r.issues.some((i) => i.level === 'error')) ? 1 : 0;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
